/** Promote scoped generated bytes into DSH's immutable image/file references. */
import { basename } from 'node:path'
import type { Context } from '@deepseek-ai/cordis'
import type { Agent } from '@deepseek-ai/dsh-agent'
import type {} from '@deepseek-ai/dsh-agent-preset-registry'
import type { ImageMediaType } from '@deepseek-ai/dsh-attachment'
import type {} from '@deepseek-ai/dsh-fs'
import type { ContentBlock } from '@deepseek-ai/dsh-llm'
import { MediaExecutionError } from './executor.ts'
import type { MediaGenerateResult } from './media.ts'
export async function nativeMediaAttachments(
  ctx: Context,
  agent: Agent,
  result: MediaGenerateResult,
  signal: AbortSignal,
  limit: number,
): Promise<ContentBlock[]> {
  const attachments =
    ctx.get('agentPresets')?.serviceFor(agent, 'attachments') ??
    agent.ctx.get('attachments') ??
    ctx.get('attachments')
  if (!attachments || !result.files.length) return []
  const fs =
    ctx.get('agentPresets')?.serviceFor(agent, 'fs') ?? agent.ctx.get('fs') ?? ctx.get('fs')
  if (!fs || !agent.session.header.cwd)
    throw new MediaExecutionError('Generated attachments require the admitted filesystem', 'INPUT')
  const blocks: ContentBlock[] = []
  let remaining = limit
  try {
    for (const file of result.files) {
      signal.throwIfAborted()
      const target = await fs.resolve(file.path, { cwd: agent.session.header.cwd, signal })
      const workspace = await fs.resolve(agent.session.header.cwd, { signal })
      if (!fs.contains(workspace, target))
        throw new MediaExecutionError(
          'Generated attachments must belong to this workspace',
          'INPUT',
        )
      const bytes = await fs.readBytes(target, signal, remaining)
      if (!bytes.byteLength || bytes.byteLength > remaining)
        throw new MediaExecutionError('Generated attachments exceed their byte budget', 'NO_OUTPUT')
      remaining -= bytes.byteLength
      const name = basename(file.path)
      if (
        file.modality === 'image' &&
        ['image/png', 'image/jpeg', 'image/webp', 'image/gif'].includes(file.mime)
      )
        blocks.push({
          type: 'image',
          attachment: await attachments.saveImage({
            data: bytes,
            name,
            mediaType: file.mime as ImageMediaType,
          }),
        })
      else
        blocks.push({ type: 'file', attachment: await attachments.saveFile({ data: bytes, name }) })
      signal.throwIfAborted()
    }
    return blocks
  } catch (error) {
    await result.rollback?.()
    throw error
  }
}
